const STORAGE_KEY='novalog-cedis-v2';
const processes=['Acceso','Recepción','Almacenamiento','Preparación de pedidos','Inspección de unidades','Despacho','Incidentes'];
const diagnosisCriteria=[
 ['D-01','Existe un responsable de seguridad identificado.'],['D-02','El alcance de las operaciones evaluadas está documentado.'],
 ['D-03','Se controlan los accesos al CEDIS.'],['D-04','Se verifica la identidad de visitantes y transportistas.'],
 ['D-05','Se controlan llaves, tarjetas o credenciales.'],['D-06','Se identifican las áreas restringidas.'],
 ['D-07','Se verifica documentación de recepción y despacho.'],['D-08','Las inspecciones de unidades se registran.'],
 ['D-09','Los incidentes se documentan y se atienden.'],['D-10','Se revisan controles y se da seguimiento a hallazgos.']
];
const auditCriteria=['Alcance documentado','Responsables identificados','Riesgos identificados','Riesgos prioritarios tratados','Accesos registrados','Identidad verificada','Recepción documentada','Inspecciones documentadas','Anomalías atendidas','Incidentes seguidos','Acciones con responsables y fechas','Eficacia revisada'];
const inspectionPoints=['Identificación de la unidad','Correspondencia entre unidad y documentos','Identificación del conductor','Autorización de ingreso o salida','Condiciones externas visibles','Puertas y mecanismos de cierre','Sellos de seguridad, cuando correspondan','Paredes externas visibles','Techo y zonas accesibles de forma segura','Piso y superficie de carga','Interior de caja/remolque cuando sea seguro','Compartimentos pertinentes y accesibles','Daños o alteraciones visibles no explicadas','Condiciones de limpieza compatibles con la carga','Correspondencia entre mercancía y documentos','Registro de anomalías','Autorización final y registro de liberación'];
const seed=()=>({scope:{name:'NovaLog CEDIS',activity:'Centro de distribución de mercancía de consumo general',location:'Parque logístico ficticio, México',responsible:'Responsable del CEDIS',objective:'Prevenir accesos no autorizados, pérdidas de trazabilidad y liberaciones inseguras.',processes:[...processes],exclusions:'Certificación formal, investigación criminal, mercancías peligrosas e integración con sistemas reales.',review:new Date().toISOString().slice(0,10)},diagnosis:diagnosisCriteria.map(([id,criterion])=>({id,criterion,result:'Pendiente',observation:'',evidence:'',evaluator:'',date:''})),risks:[
 {id:'R-01',process:'Acceso',threat:'Ingreso de persona no autorizada',vulnerability:'Control de acceso incompleto',consequence:'Acceso indebido a mercancía o instalaciones',probability:4,impact:5,residualProbability:2,residualImpact:3,controls:'Registro de entradas y salidas',treatment:'Reducir',responsible:'Guardia de seguridad',review:'',status:'Abierto'},
 {id:'R-02',process:'Despacho',threat:'Documentación de transporte incompleta',vulnerability:'Validación documental inconsistente',consequence:'Entrega a unidad o persona no validada',probability:3,impact:4,residualProbability:2,residualImpact:2,controls:'Validación documental antes del despacho',treatment:'Reducir',responsible:'Supervisor de embarques',review:'',status:'Abierto'},
 {id:'R-03',process:'Inspección de unidades',threat:'Inspección de unidad incompleta',vulnerability:'Puntos de revisión sin terminar',consequence:'Anomalía no detectada antes del despacho',probability:4,impact:4,residualProbability:2,residualImpact:2,controls:'Inspección documentada de unidades',treatment:'Reducir',responsible:'Auxiliar de almacén',review:'',status:'Abierto'},
 {id:'R-04',process:'Recepción',threat:'Diferencias entre mercancía y documentos',vulnerability:'Conciliación no documentada',consequence:'Pérdida o falta de trazabilidad',probability:3,impact:4,residualProbability:2,residualImpact:2,controls:'Conciliación de mercancía y documentos',treatment:'Reducir',responsible:'Auxiliar de almacén',review:'',status:'Abierto'},
 {id:'R-05',process:'Incidentes',threat:'Incidente no reportado',vulnerability:'Seguimiento insuficiente',consequence:'Repetición del problema y falta de evidencia',probability:4,impact:4,residualProbability:3,residualImpact:3,controls:'Registro y notificación de incidentes',treatment:'Reducir',responsible:'Responsable del CEDIS',review:'',status:'Abierto'}],controls:[
 {id:'C-01',name:'Registro de entradas y salidas',risks:'R-01',objective:'Trazar cada acceso al CEDIS',activity:'Registrar identidad, hora y motivo',executor:'Guardia de seguridad',supervisor:'Responsable del CEDIS',frequency:'Cada evento',evidence:'Bitácora de acceso',expected:'100% de accesos registrados',status:'Activo',review:''},
 {id:'C-02',name:'Verificación de identidad',risks:'R-01/R-02',objective:'Confirmar visitantes y transportistas',activity:'Validar identificación y autorización',executor:'Guardia de seguridad',supervisor:'Supervisor de embarques',frequency:'Cada evento',evidence:'Registro de visitantes',expected:'Identidad confirmada',status:'Activo',review:''},
 {id:'C-03',name:'Autorización de zonas restringidas',risks:'R-01',objective:'Limitar acceso a áreas críticas',activity:'Revisar credencial y permiso',executor:'Guardia de seguridad',supervisor:'Responsable del CEDIS',frequency:'Cada evento',evidence:'Bitácora de zonas',expected:'Sin accesos no autorizados',status:'Activo',review:''},
 {id:'C-04',name:'Validación documental antes del despacho',risks:'R-02',objective:'Asegurar entrega documentada',activity:'Comparar pedido, unidad y documentos',executor:'Supervisor de embarques',supervisor:'Responsable del CEDIS',frequency:'Cada despacho',evidence:'Checklist documental',expected:'Documentación completa',status:'Activo',review:''},
 {id:'C-05',name:'Inspección documentada de unidades',risks:'R-03',objective:'Detectar anomalías antes de liberar',activity:'Completar los 17 puntos de revisión',executor:'Auxiliar de almacén',supervisor:'Supervisor de embarques',frequency:'Cada unidad',evidence:'Folio de inspección',expected:'Sin puntos obligatorios pendientes',status:'Activo',review:''},
 {id:'C-06',name:'Conciliación de mercancía y documentos',risks:'R-04',objective:'Conservar trazabilidad',activity:'Comparar cantidades y referencias',executor:'Auxiliar de almacén',supervisor:'Supervisor de embarques',frequency:'Cada recepción',evidence:'Formato de conciliación',expected:'Sin diferencias sin explicar',status:'Activo',review:''},
 {id:'C-07',name:'Registro y notificación de incidentes',risks:'R-05',objective:'Asegurar respuesta y seguimiento',activity:'Registrar, proteger, investigar y escalar',executor:'Responsable del CEDIS',supervisor:'Responsable del CEDIS',frequency:'Cada incidente',evidence:'Folio y evidencia',expected:'Incidente atendido',status:'Activo',review:''},
 {id:'C-08',name:'Revisión periódica de controles',risks:'Todos',objective:'Verificar vigencia y eficacia',activity:'Revisar resultados y hallazgos',executor:'Responsable del CEDIS',supervisor:'Responsable del CEDIS',frequency:'Mensual',evidence:'Minuta de revisión',expected:'Controles actualizados',status:'Activo',review:''}],inspections:[],incidents:[],audit:[],actions:[],updatedAt:new Date().toISOString()});
function createCaseExample(){
  const example=seed();
  example.scope={...example.scope,objective:'Evaluar control de acceso, recepción, almacenamiento, inspección de unidades, despacho y seguimiento de incidentes; no se evalúa toda la cadena de suministro.'};
  example.diagnosis=example.diagnosis.map((d,i)=>({...d,result:i<6?'Parcial':'Pendiente',observation:i<6?'El caso muestra controles definidos, pero evidencia incompleta.':'Se requiere revisar el caso y sus registros.',evidence:i<6?'Registro incompleto de acceso y despacho':'No se dispone de evidencia',evaluator:'Equipo de evaluación',date:new Date().toISOString().slice(0,10)}));
  example.risks[0]={...example.risks[0],threat:'Ingreso sin verificación completa',vulnerability:'Registro de identidad del conductor incompleto',consequence:'Acceso no autorizado a instalaciones o mercancía',probability:3,impact:4,residualProbability:2,residualImpact:2,responsible:'Guardia de seguridad'};
  example.risks[1]={...example.risks[1],threat:'Unidad liberada con inspección incompleta',vulnerability:'No existe bloqueo claro antes de liberar',consequence:'Anomalía no detectada antes del despacho',probability:3,impact:4,residualProbability:2,residualImpact:2,responsible:'Supervisor de embarques'};
  example.risks[2]={...example.risks[2],threat:'Incidente sin seguimiento formal',vulnerability:'Atención verbal sin causa ni acción',consequence:'Repetición del problema y falta de trazabilidad',probability:4,impact:3,residualProbability:2,residualImpact:2,responsible:'Responsable del CEDIS'};
  const points=inspectionPoints.map((_,i)=>i===15?'No conforme':i===16?'Pendiente':'Conforme');
  const notes=inspectionPoints.map((_,i)=>i===15?'Registro de anomalías no documentado en el caso.':i===16?'Autorización final pendiente; no liberar la unidad.':'Revisado conforme al caso.');
  example.inspections=[{folio:'INS-001',dateTime:new Date().toISOString().slice(0,16),carrier:'Transportista externo de prueba',driver:'Operador de prueba OP-07',plate:'NL-024',trailer:'No aplica',shipment:'EMB-101',inspector:'Auxiliar de almacén asignado',evidence:'Registro incompleto; no hay prueba de aplicación completa del control.',result:'No liberada',points,pointNotes:notes,observations:'La inspección quedó incompleta y la salida debe detenerse hasta resolver los puntos pendientes.'}];
  example.incidents=[{folio:'INC-001',dateTime:new Date().toISOString().slice(0,16),place:'Acceso y despacho del CEDIS',category:'Incumplimiento de procedimiento',description:'Falta de registro completo de una revisión de acceso y seguimiento formal insuficiente.',process:'Acceso',responsible:'Responsable del CEDIS',immediate:'Detener la liberación hasta completar la revisión y conservar la evidencia.',evidence:'Registro incompleto; no se dispone de evidencia de que el control se aplicara correctamente.',severity:'Media',status:'En atención'}];
  example.auditDetails=auditCriteria.map((criterion,i)=>({criterion,result:[0,1,2,7,8].includes(i)?'No conforme':i===11?'Pendiente':'Conforme',evidence:[0,1,2,7,8].includes(i)?'Registro incompleto del caso':'Datos de demostración del ejercicio',comment:[0,1,2,7,8].includes(i)?'Requiere evidencia y seguimiento formal.':''}));
  example.audit=[{date:new Date().toISOString().slice(0,10),auditor:'Equipo de evaluación',result:'No conforme'}];
  example.actions=[{folio:'AC-001',origin:'Auditoría / inspección INS-001',description:'Incorporar autorización obligatoria y lista de verificación antes de liberar una unidad.',evidence:'NC-01: inspección de NL-024 incompleta.',risk:'R-02',correction:'Completar la inspección de NL-024 y mantenerla no liberada.',cause:'El flujo de despacho no obliga a confirmar la inspección completa antes de liberar.',action:'Actualizar SOP-04, comunicar el cambio al personal y supervisar su aplicación.',responsible:'Supervisor de embarques',due:new Date(Date.now()+5*86400000).toISOString().slice(0,10),status:'En proceso',implementationEvidence:'Procedimiento actualizado y constancia de comunicación (ejemplo pendiente de adjuntar).',effectiveness:'Revisar las siguientes 5 inspecciones y confirmar que ninguna se libere con puntos críticos pendientes.',closedAt:''}];
  return example;
}
let state=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')||createCaseExample(); let currentView='dashboard';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{state.updatedAt=new Date().toISOString();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));};
const toast=m=>{const e=$('#toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)};
const riskScore=r=>Number(r.probability)*Number(r.impact), riskLevel=s=>s>=17?'Crítico':s>=10?'Alto':s>=5?'Moderado':'Bajo', riskClass=l=>l.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const page=(title,subtitle,body,actions='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="action-row">${actions}</div></div>${body}`;
const field=(label,name,value='',type='text',full=false)=>`<div class="field${full?' full':''}"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='date'?'':''}></div>`;
const preset=(name,label='Cargar ejemplo del caso')=>`<div class="preset-bar"><span><b>¿Necesitas ayuda?</b> Usa una opción preestablecida y edítala si lo deseas.</span><button type="button" class="secondary-btn" data-preset="${name}">${label}</button></div>`;
function dashboard(){const high=state.risks.filter(r=>riskScore(r)>=10).length, openInc=state.incidents.filter(i=>i.status!=='Cerrado').length, pending=state.actions.filter(a=>a.status!=='Cerrada').length, overdue=state.actions.filter(a=>a.status!=='Cerrada'&&a.due&&a.due<new Date().toISOString().slice(0,10)).length;const levels=['Bajo','Moderado','Alto','Crítico'].map(l=>({l,n:state.risks.filter(r=>riskLevel(riskScore(r))===l).length}));return page('Panel principal','Resumen operativo de NovaLog CEDIS · actualizado '+new Date(state.updatedAt).toLocaleString('es-MX'),`<div class="grid stats"><div class="card stat"><span class="stat-label">Riesgos registrados</span><b class="stat-value blue">${state.risks.length}</b><span class="stat-foot">Matriz vigente</span></div><div class="card stat"><span class="stat-label">Riesgos altos/críticos</span><b class="stat-value red">${high}</b><span class="stat-foot">Requieren tratamiento</span></div><div class="card stat"><span class="stat-label">Inspecciones realizadas</span><b class="stat-value green">${state.inspections.length}</b><span class="stat-foot">Unidades documentadas</span></div><div class="card stat"><span class="stat-label">Incidentes abiertos</span><b class="stat-value orange">${openInc}</b><span class="stat-foot">Con seguimiento pendiente</span></div><div class="card stat"><span class="stat-label">Acciones pendientes</span><b class="stat-value blue">${pending}</b><span class="stat-foot">${overdue} vencidas</span></div></div><div class="grid two-col"><section class="card"><h2 class="section-title">Semáforo de riesgos</h2>${levels.map(x=>`<div style="margin:14px 0"><div style="display:flex;justify-content:space-between"><span>${x.l}</span><b>${x.n}</b></div><div class="bar"><i style="width:${state.risks.length?x.n/state.risks.length*100:0}%;background:${x.l==='Crítico'?'#c43d4b':x.l==='Alto'?'#e58c22':x.l==='Moderado'?'#e5ba45':'#28a985'}"></i></div></div>`).join('')}</section><section class="card"><h2 class="section-title">Pendientes prioritarios</h2>${overdue?`<div class="notice">Hay ${overdue} acción(es) correctiva(s) vencida(s).</div>`:'<div class="notice" style="background:#e7f8f1;color:#08745f;border-color:#b8ead8">No hay acciones vencidas.</div>'}<h3>Última auditoría</h3><p class="muted">${state.audit.length?esc(state.audit.at(-1).result):'Sin auditorías registradas'}</p><button class="primary-btn" data-view="audit">Ver indicadores y auditoría</button></section></div>`);}
function scope(){return page('Información y alcance','Define la ficha del centro de distribución y sus límites.',`<section class="card"><form id="scopeForm">${preset('scope-case')}<div class="form-grid">${field('Nombre del CEDIS','name',state.scope.name)}${field('Actividad','activity',state.scope.activity)}${field('Ubicación ficticia','location',state.scope.location)}${field('Responsable','responsible',state.scope.responsible)}${field('Fecha de revisión','review',state.scope.review,'date')}<div class="field full"><label>Procesos incluidos</label><div class="action-row">${processes.map(p=>`<label><input type="checkbox" name="process" value="${esc(p)}" ${state.scope.processes.includes(p)?'checked':''}> ${p}</label>`).join('')}</div></div><div class="field full"><label for="objective">Objetivo de seguridad</label><textarea id="objective">${esc(state.scope.objective)}</textarea></div><div class="field full"><label for="exclusions">Exclusiones justificadas</label><textarea id="exclusions">${esc(state.scope.exclusions)}</textarea></div></div><div class="form-actions"><button class="primary-btn">Guardar ficha</button><button type="button" class="secondary-btn" data-print>Imprimir ficha</button></div></form></section>`);}
function diagnosis(){const applicable=state.diagnosis.filter(d=>d.result!=='No aplica'), points=state.diagnosis.reduce((n,d)=>n+(d.result==='Cumple'?1:d.result==='Parcial'?.5:0),0), pct=applicable.length?Math.round(points/applicable.length*100):null;return page('Diagnóstico inicial','Evalúa las condiciones existentes; “No aplica” requiere justificación.',`<section class="card"><div style="display:flex;justify-content:space-between;align-items:center"><h2 class="section-title">Cumplimiento interno</h2><strong class="stat-value blue">${pct===null?'Sin datos':pct+'%'}</strong></div><form id="diagnosisForm" class="checklist">${preset('diagnosis-case')} ${state.diagnosis.map((d,i)=>`<div class="check-row"><b>${d.id}</b><div><strong>${esc(d.criterion)}</strong><small>${esc(d.observation||'Sin observación')}</small></div><select name="result-${i}"><option ${d.result==='Pendiente'?'selected':''}>Pendiente</option><option ${d.result==='Cumple'?'selected':''}>Cumple</option><option ${d.result==='Parcial'?'selected':''}>Parcial</option><option ${d.result==='No cumple'?'selected':''}>No cumple</option><option ${d.result==='No aplica'?'selected':''}>No aplica</option></select></div>`).join('')}<div class="form-actions"><button class="primary-btn">Guardar diagnóstico</button></div></form></section>`);}
function risks(){return page('Matriz de riesgos','Identifica, prioriza y trata riesgos con escalas internas del simulador.',`<section class="card"><form id="riskForm">${preset('risk-case')}<div class="form-grid">${field('Proceso','process','Acceso')} ${field('Amenaza','threat')} ${field('Vulnerabilidad','vulnerability')} ${field('Consecuencia','consequence')} ${field('Probabilidad (1-5)','probability','3','number')} ${field('Impacto (1-5)','impact','3','number')} ${field('Responsable','responsible')} ${field('Fecha de revisión','review','','date')}<div class="field"><label for="treatment">Tratamiento</label><select id="treatment"><option>Evitar</option><option selected>Reducir</option><option>Compartir/transferir</option><option>Aceptar con justificación</option></select></div><div class="field full"><label for="controls">Controles existentes</label><textarea id="controls"></textarea></div></div><div class="form-actions"><button class="primary-btn">Agregar riesgo</button></div></form></section><section class="card" style="margin-top:18px"><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Proceso / amenaza</th><th>Inicial</th><th>Nivel</th><th>Residual</th><th>Tratamiento</th><th>Estado</th><th></th></tr></thead><tbody>${state.risks.map((r,i)=>{let s=riskScore(r),l=riskLevel(s),rs=Number(r.residualProbability)*Number(r.residualImpact),rl=riskLevel(rs);return `<tr><td><b>${r.id}</b></td><td><b>${esc(r.threat)}</b><br><span class="muted">${esc(r.process)}</span></td><td>${s}</td><td><span class="pill ${riskClass(l)}">${l}</span></td><td>${rs} · <span class="pill ${riskClass(rl)}">${rl}</span></td><td>${esc(r.treatment)}</td><td>${esc(r.status)}</td><td><button class="danger-btn" data-delete-risk="${i}">Eliminar</button></td></tr>`}).join('')}</tbody></table></div></section>`);}
function controls(){return page('Controles y procedimientos','Catálogo de medidas operativas, responsables, frecuencias y evidencias.',`<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>ID / control</th><th>Riesgos</th><th>Actividad</th><th>Ejecutor</th><th>Frecuencia</th><th>Evidencia</th><th>Estado</th></tr></thead><tbody>${state.controls.map(c=>`<tr><td><b>${c.id}</b><br>${esc(c.name)}</td><td>${esc(c.risks)}</td><td>${esc(c.activity)}</td><td>${esc(c.executor)}</td><td>${esc(c.frequency)}</td><td>${esc(c.evidence)}</td><td><span class="pill closed">${esc(c.status)}</span></td></tr>`).join('')}</tbody></table></div></section>`);}
function inspections(){return page('Inspección de unidades','Completa los 17 puntos; no se puede liberar una unidad con pendientes obligatorios.',`<section class="card"><form id="inspectionForm">${preset('inspection-case')}<div class="form-grid">${field('Folio','folio','INS-'+String(state.inspections.length+1).padStart(3,'0'))}${field('Fecha y hora','dateTime',new Date().toISOString().slice(0,16),'datetime-local')}${field('Transportista','carrier')}${field('Conductor','driver')}${field('Matrícula','plate')}${field('Pedido/embarque','shipment')}${field('Inspector','inspector')}<div class="field"><label for="inspectionResult">Resultado</label><select id="inspectionResult"><option>En proceso</option><option>Liberada</option><option>No liberada</option></select></div></div><h2 class="section-title">Puntos de revisión</h2><div class="checklist">${inspectionPoints.map((p,i)=>`<div class="check-row"><b>${i+1}</b><span>${p}</span><select name="point-${i}"><option>Pendiente</option><option>Conforme</option><option>No conforme</option><option>No aplica</option></select></div>`).join('')}</div><div class="field full"><label for="inspectionObs">Observaciones</label><textarea id="inspectionObs"></textarea></div><div class="form-actions"><button class="primary-btn">Guardar inspección</button></div></form></section>${state.inspections.length?`<section class="card" style="margin-top:18px"><h2 class="section-title">Historial</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Folio</th><th>Fecha</th><th>Unidad</th><th>Resultado</th><th>Conformes</th></tr></thead><tbody>${state.inspections.map(x=>`<tr><td>${esc(x.folio)}</td><td>${esc(x.dateTime)}</td><td>${esc(x.plate)}</td><td><span class="pill ${x.result==='Liberada'?'closed':'open'}">${esc(x.result)}</span></td><td>${x.points.filter(p=>p==='Conforme').length}/17</td></tr>`).join('')}</tbody></table></div></section>`:''}`);}
function incidents(){return page('Registro de incidentes','Documenta hechos, respuesta, evidencia y seguimiento.',`<section class="card"><form id="incidentForm">${preset('incident-case')}<div class="form-grid">${field('Folio','folio','INC-'+String(state.incidents.length+1).padStart(3,'0'))}${field('Fecha y hora','dateTime',new Date().toISOString().slice(0,16),'datetime-local')}${field('Lugar','place')}${field('Descripción objetiva','description','', 'text',true)}<div class="field"><label for="category">Categoría</label><select id="category"><option>Acceso no autorizado</option><option>Diferencia documental</option><option>Anomalía de unidad</option><option>Faltante/diferencia de mercancía</option><option>Sello alterado</option><option>Incumplimiento de procedimiento</option><option>Pérdida documental</option><option>Otro</option></select></div>${field('Proceso','process','Acceso')}${field('Responsable','responsible')}${field('Medida inmediata','immediate','', 'text',true)}${field('Evidencia','evidence','', 'text',true)}<div class="field"><label for="severity">Gravedad interna</label><select id="severity"><option>Baja</option><option>Media</option><option>Alta</option><option>Crítica</option></select></div></div><div class="form-actions"><button class="primary-btn">Registrar incidente</button></div></form></section><section class="card" style="margin-top:18px"><div class="table-wrap"><table class="data-table"><thead><tr><th>Folio</th><th>Categoría</th><th>Descripción</th><th>Gravedad</th><th>Estado</th></tr></thead><tbody>${state.incidents.length?state.incidents.map((x,i)=>`<tr><td>${esc(x.folio)}</td><td>${esc(x.category)}</td><td>${esc(x.description)}</td><td><span class="pill ${x.severity==='Crítica'?'critical':''}">${esc(x.severity)}</span></td><td><select data-incident-status="${i}">${['Nuevo','En revisión','En atención','Pendiente de acción correctiva','Cerrado'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No hay incidentes registrados.</td></tr>'}</tbody></table></div></section>`);}
function audit(){const diag=state.diagnosis.filter(x=>x.result!=='Pendiente'),diagPct=diag.length?Math.round(diag.reduce((n,x)=>n+(x.result==='Cumple'?1:x.result==='Parcial'?.5:0),0)/diag.filter(x=>x.result!=='No aplica').length*100):null;const complete=state.inspections.filter(x=>x.result!=='En proceso').length;return page('Indicadores y auditoría','Mide desempeño con periodos y tamaños de muestra; sin datos no se divide entre cero.',`<div class="grid stats"><div class="card stat"><span class="stat-label">Cumplimiento diagnóstico</span><b class="stat-value blue">${diagPct===null||Number.isNaN(diagPct)?'Sin datos':diagPct+'%'}</b><span class="stat-foot">Muestra: ${diag.length}</span></div><div class="card stat"><span class="stat-label">Inspecciones completas</span><b class="stat-value green">${state.inspections.length?Math.round(complete/state.inspections.length*100)+'%':'Sin datos'}</b><span class="stat-foot">Muestra: ${state.inspections.length}</span></div><div class="card stat"><span class="stat-label">Incidentes atendidos</span><b class="stat-value orange">${state.incidents.length?Math.round(state.incidents.filter(x=>x.status==='Cerrado').length/state.incidents.length*100)+'%':'Sin datos'}</b><span class="stat-foot">Muestra: ${state.incidents.length}</span></div><div class="card stat"><span class="stat-label">Acciones cerradas</span><b class="stat-value green">${state.actions.length?Math.round(state.actions.filter(x=>x.status==='Cerrada').length/state.actions.length*100)+'%':'Sin datos'}</b><span class="stat-foot">Muestra: ${state.actions.length}</span></div></div><section class="card" style="margin-top:18px"><form id="auditForm">${preset('audit-case')}<div class="form-grid">${field('Fecha','auditDate',new Date().toISOString().slice(0,10),'date')}${field('Auditor','auditor')}<div class="field full"><label for="auditResult">Resultado general</label><select id="auditResult"><option>Sin datos</option><option>Conforme</option><option>Con observaciones</option><option>No conforme</option></select></div></div><div class="form-actions"><button class="primary-btn">Registrar resultado de auditoría</button></div></form></section>`);}
function actions(){return page('No conformidades y acciones correctivas','Analiza causas, asigna acciones y verifica eficacia antes de cerrar.',`<section class="card"><form id="actionForm">${preset('action-case')}<div class="form-grid">${field('Folio','folio','AC-'+String(state.actions.length+1).padStart(3,'0'))}${field('Origen','origin','Incidente')}${field('Descripción','description','', 'text',true)}${field('Evidencia','evidence','', 'text',true)}${field('Riesgo relacionado','risk','R-01')}${field('Corrección inmediata','correction','', 'text',true)}${field('Causa raíz (cinco porqués)','cause','', 'text',true)}${field('Acción correctiva','action','', 'text',true)}${field('Responsable','responsible')}${field('Fecha compromiso','due','','date')}<div class="field"><label for="actionStatus">Estado</label><select id="actionStatus"><option>Abierta</option><option>En proceso</option><option>Pendiente de verificación</option><option>Cerrada</option><option>Reabierta</option></select></div></div><div class="form-actions"><button class="primary-btn">Guardar acción</button></div></form></section><section class="card" style="margin-top:18px"><div class="table-wrap"><table class="data-table"><thead><tr><th>Folio</th><th>Descripción</th><th>Responsable</th><th>Compromiso</th><th>Estado</th></tr></thead><tbody>${state.actions.length?state.actions.map((a,i)=>`<tr><td>${esc(a.folio)}</td><td>${esc(a.description)}</td><td>${esc(a.responsible)}</td><td>${esc(a.due)}</td><td><select data-action-status="${i}">${['Abierta','En proceso','Pendiente de verificación','Cerrada','Reabierta'].filter(s=>s!=='Cerrada'||(a.implementationEvidence&&a.effectiveness&&a.closedAt)||a.status==='Cerrada').map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No hay acciones correctivas.</td></tr>'}</tbody></table></div></section>`);}
function reports(){return page('Reportes y evidencias','Consulta el expediente del ejercicio y utiliza la impresión del navegador para guardar PDF.',`<section class="card report-sheet"><h2>Expediente ${esc(state.scope.name)}</h2><p class="muted">Generado: ${new Date().toLocaleString('es-MX')} · Datos ficticios académicos</p><div class="report-section"><h3>Ficha de alcance</h3><p><b>Actividad:</b> ${esc(state.scope.activity)}<br><b>Ubicación:</b> ${esc(state.scope.location)}<br><b>Responsable:</b> ${esc(state.scope.responsible)}<br><b>Procesos:</b> ${state.scope.processes.map(esc).join(', ')}</p></div><div class="report-section"><h3>Resumen de registros</h3><p>Diagnósticos: ${state.diagnosis.length} · Riesgos: ${state.risks.length} · Controles: ${state.controls.length} · Inspecciones: ${state.inspections.length} · Incidentes: ${state.incidents.length} · Acciones: ${state.actions.length}</p></div><div class="report-section"><h3>Matriz de riesgos</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Amenaza</th><th>Puntuación</th><th>Nivel</th><th>Tratamiento</th></tr></thead><tbody>${state.risks.map(r=>`<tr><td>${r.id}</td><td>${esc(r.threat)}</td><td>${riskScore(r)}</td><td>${riskLevel(riskScore(r))}</td><td>${esc(r.treatment)}</td></tr>`).join('')}</tbody></table></div></div><button class="primary-btn" data-print>Imprimir / guardar como PDF</button></section>`);}
function help(){const modules=[
 ['Panel principal','Es el resumen del ejercicio. Muestra tarjetas, semáforo y pendientes. Ejemplo: debe mostrar 5 riesgos, 1 inspección realizada, 1 incidente abierto y 1 acción en proceso con los datos de NL-024.'],
 ['Información y alcance','Define el CEDIS, actividad, ubicación, responsable, procesos, objetivo y exclusiones. Ejemplo: NovaLog CEDIS; recepción, almacenamiento y despacho; ubicación ficticia en México; responsable del CEDIS.'],
 ['Diagnóstico inicial','Evalúa D-01 a D-10. Ejemplo: en D-04 escribe “Parcial”, observación “No quedó completo el registro del conductor OP-07”, evidencia “Registro incompleto” y evaluador “Equipo de evaluación”.'],
 ['Matriz de riesgos','Registra amenaza, vulnerabilidad, consecuencia, probabilidad e impacto. Ejemplo: “Ingreso sin verificación completa”, probabilidad 3, impacto 4: puntuación 12, nivel Alto, riesgo R-01.'],
 ['Controles y procedimientos','Consulta controles y SOP. Ejemplo: para la inspección incompleta usa C-05 “Inspección documentada de unidades” y SOP-04 “Despacho”, que obliga a detener la salida si faltan puntos.'],
 ['Inspecciones','Revisa 17 puntos. Ejemplo: folio INS-001, unidad NL-024, conductor OP-07, embarque EMB-101; marca el punto de autorización final como Pendiente y la unidad como No liberada.'],
 ['Incidentes','Registra hechos, categoría, lugar, gravedad, proceso, responsable, medida y evidencia. Ejemplo: INC-001, incumplimiento de procedimiento, “falta de registro completo de una revisión de acceso”, estado En atención.'],
 ['Indicadores y auditoría','Calcula KPI y permite revisar los 12 criterios. Ejemplo: marca No conforme “Inspecciones documentadas” y “Acciones con responsables y fechas”, adjunta como evidencia el registro incompleto y agrega un comentario.'],
 ['Acciones correctivas','Documenta causa, acción, responsable, plazo y eficacia. Ejemplo: AC-001, responsable Supervisor de embarques, plazo de 5 días hábiles, actualizar SOP-04 y revisar las siguientes 5 inspecciones.'],
 ['Reportes y evidencias','Presenta el expediente y permite guardarlo como PDF. Ejemplo: el reporte incluye la ficha de NovaLog, los riesgos R-01 a R-05, INS-001, INC-001, la auditoría y AC-001.']
 ];return page('Ayuda y funcionamiento','Guía rápida para utilizar NovaLog CEDIS y entender sus resultados.',`<section class="card"><div class="notice"><b>Flujo recomendado:</b> 1) define el alcance, 2) realiza el diagnóstico, 3) registra y trata riesgos, 4) documenta controles e inspecciones, 5) registra incidentes, 6) audita resultados y 7) crea acciones correctivas.</div><h2 class="section-title">¿Para qué sirve cada módulo?</h2><div class="grid two-col">${modules.map(([name,description])=>`<article class="card"><h3>${name}</h3><p class="muted">${description}</p></article>`).join('')}</div><h2 class="section-title">Reglas importantes</h2><ul><li>Los datos iniciales son ficticios y sirven únicamente para demostrar el simulador.</li><li>La puntuación de riesgo y el porcentaje de cumplimiento son convenciones internas de este ejercicio; no son una certificación.</li><li>“No aplica” debe tener una justificación antes de considerarse excluido.</li><li>Los indicadores muestran “Sin datos” cuando no existe una muestra suficiente.</li><li>Los datos de esta versión se guardan localmente en el navegador. No se envían a un servidor.</li><li>No se deben introducir claves administrativas o secretos en el frontend.</li></ul><h2 class="section-title">Cómo empezar</h2><p>Usa el menú lateral para entrar a cada módulo. Completa los campos obligatorios, pulsa el botón de guardar y confirma el aviso que aparece en la esquina inferior derecha. Puedes volver al Panel principal en cualquier momento para ver cómo cambian los indicadores.</section>`);}
const views={dashboard,scope,diagnosis,risks,controls,inspections,incidents,audit,actions,reports,help};
function render(view=currentView){currentView=view;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#app').innerHTML=views[view]();bindForms();}
function val(id){return $('#'+id)?.value.trim()||''}
function setPresetValue(id,value){const element=$('#'+id);if(element)element.value=value}
function applyPreset(name){
  const today=new Date().toISOString().slice(0,10), dateTime=new Date().toISOString().slice(0,16);
  const values={
    'scope-case':{name:'NovaLog CEDIS',activity:'Centro de distribución de mercancía de consumo general',location:'Parque logístico ficticio, México',responsible:'Responsable del CEDIS',review:today,objective:'Evaluar el control de acceso, recepción, almacenamiento, inspección de unidades, despacho y seguimiento de incidentes.',exclusions:'Certificación formal, investigación criminal, mercancías peligrosas e integración con sistemas reales.'},
    'risk-case':{process:'Acceso',threat:'Ingreso sin verificación completa',vulnerability:'Registro de identidad del conductor incompleto',consequence:'Acceso no autorizado a instalaciones o mercancía',probability:'3',impact:'4',responsible:'Guardia de seguridad',review:today,controls:'Registro de entradas y salidas y verificación de identidad.'},
    'inspection-case':{folio:'INS-'+String(state.inspections.length+1).padStart(3,'0'),dateTime,carrier:'Transportista externo de prueba',driver:'Operador de prueba OP-07',plate:'NL-024',shipment:'EMB-101',inspector:'Auxiliar de almacén asignado',inspectionResult:'No liberada',inspectionObs:'La inspección quedó incompleta; la salida debe detenerse hasta resolver los puntos pendientes.'},
    'incident-case':{folio:'INC-'+String(state.incidents.length+1).padStart(3,'0'),dateTime,place:'Acceso y despacho del CEDIS',description:'Falta de registro completo de una revisión de acceso y seguimiento formal insuficiente.',category:'Incumplimiento de procedimiento',process:'Acceso',responsible:'Responsable del CEDIS',immediate:'Detener la liberación hasta completar la revisión y conservar la evidencia.',evidence:'Registro incompleto; no se dispone de evidencia de aplicación completa del control.',severity:'Media'},
    'audit-case':{auditDate:today,auditor:'Equipo de evaluación'},
    'action-case':{folio:'AC-'+String(state.actions.length+1).padStart(3,'0'),origin:'Auditoría / inspección INS-001',description:'Incorporar autorización obligatoria y lista de verificación antes de liberar una unidad.',evidence:'NC-01: inspección de NL-024 incompleta.',risk:'R-02',correction:'Completar la inspección de NL-024 y mantenerla no liberada.',cause:'El flujo de despacho no obliga a confirmar la inspección completa antes de liberar.',action:'Actualizar SOP-04, comunicar el cambio al personal y supervisar su aplicación.',responsible:'Supervisor de embarques',due:new Date(Date.now()+5*86400000).toISOString().slice(0,10)}
  }[name];
  if(!values)return;
  Object.entries(values).forEach(([id,value])=>setPresetValue(id,value));
  if(name==='scope-case')document.querySelectorAll('[name=process]').forEach(input=>{input.checked=processes.includes(input.value)});
  if(name==='diagnosis-case')state.diagnosis.forEach((d,i)=>{const select=$(`[name=result-${i}]`);if(select)select.value=i<6?'Parcial':'Pendiente'});
  if(name==='inspection-case')inspectionPoints.forEach((_,i)=>{const select=$(`[name=point-${i}]`);if(select)select.value=i===0?'Conforme':'Pendiente'});
  if(name==='audit-case')auditCriteria.forEach((_,i)=>{const select=$(`[name=auditResult-${i}]`);if(select)select.value=[0,1,2,7,8].includes(i)?'No conforme':i===11?'Pendiente':'Conforme'});
  toast('Ejemplo cargado. Puedes editarlo antes de guardar.');
}
function bindForms(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>render(b.dataset.view));document.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>window.print());$('#printBtn').onclick=()=>window.print();
 document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>applyPreset(b.dataset.preset));
 $('#scopeForm')?.addEventListener('submit',e=>{e.preventDefault();state.scope={...state.scope,name:val('name'),activity:val('activity'),location:val('location'),responsible:val('responsible'),review:val('review'),objective:val('objective'),exclusions:val('exclusions'),processes:[...document.querySelectorAll('[name=process]:checked')].map(x=>x.value)};save();toast('Ficha de alcance guardada');render('scope')});
 if(!window.enhancedForms) $('#diagnosisForm')?.addEventListener('submit',e=>{e.preventDefault();state.diagnosis.forEach((d,i)=>{d.result=$(`[name=result-${i}]`).value;if(d.result==='No aplica'&&!d.observation)d.observation='Justificación pendiente';d.date=new Date().toISOString().slice(0,10)});save();toast('Diagnóstico guardado');render('diagnosis')});
 $('#riskForm')?.addEventListener('submit',e=>{e.preventDefault();const p=Number(val('probability')),im=Number(val('impact'));if(![p,im].every(n=>n>=1&&n<=5)){toast('Probabilidad e impacto deben estar entre 1 y 5');return}state.risks.push({id:'R-'+String(state.risks.length+1).padStart(2,'0'),process:val('process'),threat:val('threat'),vulnerability:val('vulnerability'),consequence:val('consequence'),probability:p,impact:im,residualProbability:p,residualImpact:im,controls:val('controls'),treatment:val('treatment'),responsible:val('responsible'),review:val('review'),status:'Abierto'});save();toast('Riesgo agregado');render('risks')});
 document.querySelectorAll('[data-delete-risk]').forEach(b=>b.onclick=()=>{state.risks.splice(Number(b.dataset.deleteRisk),1);save();render('risks');toast('Riesgo eliminado')});
 if(!window.enhancedForms) $('#inspectionForm')?.addEventListener('submit',e=>{e.preventDefault();const points=inspectionPoints.map((_,i)=>$(`[name=point-${i}]`).value), pending=points.filter(x=>x==='Pendiente').length, non=points.filter(x=>x==='No conforme').length, result=val('inspectionResult');if((pending||non)&&result==='Liberada'){toast('No se puede liberar: hay puntos pendientes o no conformes');return}state.inspections.push({folio:val('folio'),dateTime:val('dateTime'),carrier:val('carrier'),driver:val('driver'),plate:val('plate'),shipment:val('shipment'),inspector:val('inspector'),result,points,observations:val('inspectionObs')});save();toast('Inspección guardada');render('inspections')});
 $('#incidentForm')?.addEventListener('submit',e=>{e.preventDefault();if(!val('description')||!val('place')){toast('Lugar y descripción son obligatorios');return}state.incidents.push({folio:val('folio'),dateTime:val('dateTime'),place:val('place'),category:val('category'),description:val('description'),process:val('process'),responsible:val('responsible'),immediate:val('immediate'),evidence:val('evidence'),severity:val('severity'),status:'Nuevo'});save();toast('Incidente registrado');render('incidents')});
 document.querySelectorAll('[data-incident-status]').forEach(s=>s.onchange=()=>{state.incidents[Number(s.dataset.incidentStatus)].status=s.value;save();toast('Estado actualizado')});
 if(!window.enhancedForms) $('#auditForm')?.addEventListener('submit',e=>{e.preventDefault();state.audit.push({date:val('auditDate'),auditor:val('auditor'),result:val('auditResult')});save();toast('Auditoría registrada');render('audit')});
 if(!window.enhancedForms) $('#actionForm')?.addEventListener('submit',e=>{e.preventDefault();if(!val('description')||!val('responsible')||!val('due')){toast('Descripción, responsable y fecha compromiso son obligatorios');return}state.actions.push({folio:val('folio'),origin:val('origin'),description:val('description'),evidence:val('evidence'),risk:val('risk'),correction:val('correction'),cause:val('cause'),action:val('action'),responsible:val('responsible'),due:val('due'),status:val('actionStatus')});save();toast('Acción correctiva guardada');render('actions')});
 document.querySelectorAll('[data-action-status]').forEach(s=>s.onchange=()=>{state.actions[Number(s.dataset.actionStatus)].status=s.value;save();toast('Estado actualizado')});
}

function normalizeState(){
  state.procedures ||= [
    {id:'SOP-01',name:'Control de accesos',purpose:'Controlar el ingreso y salida de personas y unidades.',scope:'Acceso al CEDIS',responsible:'Guardia de seguridad',steps:'Verificar identidad; validar autorización; registrar entrada o salida; escalar desviaciones.',records:'Bitácora de accesos',deviation:'Retener el acceso y avisar al responsable.'},
    {id:'SOP-02',name:'Recepción',purpose:'Asegurar la recepción documentada de mercancía.',scope:'Recepción y almacenamiento',responsible:'Auxiliar de almacén',steps:'Comparar documentos; revisar unidad; contar mercancía; registrar diferencias.',records:'Formato de recepción',deviation:'Separar la mercancía y abrir un incidente.'},
    {id:'SOP-03',name:'Inspección de unidades',purpose:'Detectar anomalías antes de liberar una unidad.',scope:'Inspección de unidades',responsible:'Auxiliar de almacén',steps:'Identificar unidad; completar 17 puntos; registrar hallazgos; liberar solo si procede.',records:'Folio de inspección',deviation:'No liberar y notificar la anomalía.'},
    {id:'SOP-04',name:'Despacho',purpose:'Validar documentos y autorización de salida.',scope:'Despacho',responsible:'Supervisor de embarques',steps:'Validar pedido; confirmar transportista; revisar inspección; registrar liberación.',records:'Checklist de despacho',deviation:'Bloquear despacho y reportar diferencia.'},
    {id:'SOP-05',name:'Reporte de incidentes',purpose:'Conservar evidencia y asegurar respuesta.',scope:'Todos los procesos',responsible:'Responsable del CEDIS',steps:'Proteger personas y área; registrar hechos; asignar seguimiento; verificar cierre.',records:'Folio de incidente',deviation:'Escalar al responsable y crear acción correctiva.'},
    {id:'SOP-06',name:'Atención de anomalías en transporte',purpose:'Contener anomalías detectadas en una unidad.',scope:'Inspección y despacho',responsible:'Supervisor de embarques',steps:'Detener liberación; documentar evidencia; evaluar gravedad; autorizar disposición.',records:'Reporte de anomalía',deviation:'Mantener unidad retenida hasta verificar la condición crítica.'}
  ];
  state.auditDetails ||= [];
  state.diagnosis.forEach(d=>{d.observation ||= ''; d.evidence ||= ''; d.evaluator ||= ''; d.date ||= ''; d.justification ||= '';});
  state.inspections.forEach(i=>{i.pointNotes ||= Array(inspectionPoints.length).fill(''); i.evidence ||= '';});
  state.actions.forEach(a=>{a.implementationEvidence ||= ''; a.effectiveness ||= ''; a.closedAt ||= '';});
}
normalizeState();

function diagnosis(){
  const applicable=state.diagnosis.filter(d=>d.result!=='No aplica'&&d.result!=='Pendiente');
  const points=state.diagnosis.reduce((n,d)=>n+(d.result==='Cumple'?1:d.result==='Parcial'?.5:0),0);
  const pct=applicable.length?Math.round(points/applicable.length*100):null;
  return page('Diagnóstico inicial','Evalúa cada criterio y conserva observación, evidencia, evaluador y fecha.',
  `<section class="card"><div style="display:flex;justify-content:space-between;align-items:center"><h2 class="section-title">Cumplimiento interno</h2><strong class="stat-value blue">${pct===null?'Sin datos':pct+'%'}</strong></div><form id="diagnosisForm" class="checklist">${preset('diagnosis-case')}${state.diagnosis.map((d,i)=>`<div class="check-row diagnosis-row"><b>${d.id}</b><div><strong>${esc(d.criterion)}</strong><input name="observation-${i}" placeholder="Observación" value="${esc(d.observation)}"><input name="evidence-${i}" placeholder="Evidencia" value="${esc(d.evidence)}"><input name="evaluator-${i}" placeholder="Evaluador" value="${esc(d.evaluator)}"><input name="date-${i}" type="date" value="${esc(d.date)}">${d.result==='No aplica'?`<input name="justification-${i}" placeholder="Justificación de No aplica" value="${esc(d.justification)}">`:''}</div><select name="result-${i}"><option ${d.result==='Pendiente'?'selected':''}>Pendiente</option><option ${d.result==='Cumple'?'selected':''}>Cumple</option><option ${d.result==='Parcial'?'selected':''}>Parcial</option><option ${d.result==='No cumple'?'selected':''}>No cumple</option><option ${d.result==='No aplica'?'selected':''}>No aplica</option></select></div>`).join('')}<div class="form-actions"><button class="primary-btn">Guardar diagnóstico</button></div></form></section>`);
}

function controls(){
  return page('Controles y procedimientos','Catálogo de controles y procedimientos SOP del CEDIS.',
  `<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>ID / control</th><th>Riesgos</th><th>Objetivo y actividad</th><th>Responsables</th><th>Frecuencia</th><th>Evidencia</th><th>Estado</th></tr></thead><tbody>${state.controls.map(c=>`<tr><td><b>${c.id}</b><br>${esc(c.name)}</td><td>${esc(c.risks)}</td><td>${esc(c.objective)}<br>${esc(c.activity)}</td><td>${esc(c.executor)} / ${esc(c.supervisor)}</td><td>${esc(c.frequency)}</td><td>${esc(c.evidence)}</td><td><span class="pill closed">${esc(c.status)}</span></td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:18px"><h2 class="section-title">Procedimientos SOP</h2><div class="grid two-col">${state.procedures.map(p=>`<article class="card"><h3>${p.id} · ${esc(p.name)}</h3><p><b>Propósito:</b> ${esc(p.purpose)}<br><b>Alcance:</b> ${esc(p.scope)}<br><b>Responsable:</b> ${esc(p.responsible)}</p><p><b>Pasos:</b> ${esc(p.steps)}</p><p><b>Registros:</b> ${esc(p.records)}<br><b>Desviación:</b> ${esc(p.deviation)}</p></article>`).join('')}</div><form id="procedureForm" style="margin-top:18px"><div class="form-grid">${field('Nombre del procedimiento','procedureName')} ${field('Responsable','procedureResponsible')} ${field('Propósito','procedurePurpose','', 'text',true)} ${field('Alcance','procedureScope')} ${field('Pasos','procedureSteps','', 'text',true)} ${field('Registros asociados','procedureRecords')} ${field('Actuación ante desviaciones','procedureDeviation','', 'text',true)}</div><div class="form-actions"><button class="primary-btn">Agregar procedimiento</button></div></form></section>`);
}

function inspections(){
  return page('Inspección de unidades','Completa los 17 puntos; toda no conformidad requiere observación y bloquea la liberación.',
  `<section class="card"><form id="inspectionForm">${preset('inspection-case')}<div class="form-grid">${field('Folio','folio','INS-'+String(state.inspections.length+1).padStart(3,'0'))}${field('Fecha y hora','dateTime',new Date().toISOString().slice(0,16),'datetime-local')}${field('Transportista','carrier')}${field('Conductor','driver')}${field('Matrícula','plate')}${field('Identificador de remolque','trailer')}${field('Pedido/embarque','shipment')}${field('Inspector','inspector')}${field('Referencia de evidencia','evidence')}<div class="field"><label for="inspectionResult">Resultado</label><select id="inspectionResult"><option>En proceso</option><option>Liberada</option><option>No liberada</option></select></div></div><h2 class="section-title">Puntos de revisión</h2><div class="checklist">${inspectionPoints.map((p,i)=>`<div class="check-row"><b>${i+1}</b><div><span>${p}</span><input name="pointNote-${i}" placeholder="Observación si aplica"></div><select name="point-${i}"><option>Pendiente</option><option>Conforme</option><option>No conforme</option><option>No aplica</option></select></div>`).join('')}</div><div class="field full"><label for="inspectionObs">Observaciones generales</label><textarea id="inspectionObs"></textarea></div><div class="form-actions"><button class="primary-btn">Guardar inspección</button></div></form></section>${state.inspections.length?`<section class="card" style="margin-top:18px"><h2 class="section-title">Historial</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Folio</th><th>Fecha</th><th>Unidad</th><th>Resultado</th><th>Anomalías</th><th>Evidencia</th></tr></thead><tbody>${state.inspections.map(x=>`<tr><td>${esc(x.folio)}</td><td>${esc(x.dateTime)}</td><td>${esc(x.plate)}</td><td><span class="pill ${x.result==='Liberada'?'closed':'open'}">${esc(x.result)}</span></td><td>${x.points.filter(p=>p==='No conforme').length}</td><td>${esc(x.evidence)}</td></tr>`).join('')}</tbody></table></div></section>`:''}`);
}

function audit(){
  const values=state.auditDetails, count=values.filter(x=>x.result!=='No aplica'&&x.result!=='Pendiente').length;
  const conform=values.filter(x=>x.result==='Conforme').length, pct=count?Math.round(conform/count*100):null;
  const inspections=state.inspections, withAnomalies=inspections.filter(x=>x.points?.includes('No conforme')).length;
  const openActions=state.actions.filter(x=>x.status!=='Cerrada').length, overdue=state.actions.filter(x=>x.status!=='Cerrada'&&x.due&&x.due<new Date().toISOString().slice(0,10)).length;
  return page('Indicadores y auditoría','KPI internos con periodo, muestra y auditoría detallada por criterio.',
  `<div class="grid stats"><div class="card stat"><span class="stat-label">Cumplimiento diagnóstico</span><b class="stat-value blue">${(()=>{const d=state.diagnosis.filter(x=>x.result!=='Pendiente'&&x.result!=='No aplica');return d.length?Math.round(d.reduce((n,x)=>n+(x.result==='Cumple'?1:x.result==='Parcial'?.5:0),0)/d.length*100)+'%':'Sin datos'})()}</b><span class="stat-foot">Muestra: ${state.diagnosis.filter(x=>x.result!=='Pendiente').length}</span></div><div class="card stat"><span class="stat-label">Inspecciones con anomalías</span><b class="stat-value red">${inspections.length?Math.round(withAnomalies/inspections.length*100)+'%':'Sin datos'}</b><span class="stat-foot">Muestra: ${inspections.length}</span></div><div class="card stat"><span class="stat-label">Acciones vencidas</span><b class="stat-value orange">${openActions?Math.round(overdue/openActions*100)+'%':'Sin datos'}</b><span class="stat-foot">${overdue} abiertas vencidas</span></div><div class="card stat"><span class="stat-label">Auditoría</span><b class="stat-value green">${pct===null?'Sin datos':pct+'%'}</b><span class="stat-foot">Muestra: ${count}</span></div></div>  <section class="card" style="margin-top:18px"><form id="auditForm">${preset('audit-case')}<div class="form-grid">${field('Fecha','auditDate',new Date().toISOString().slice(0,10),'date')}${field('Auditor','auditor')}</div><h2 class="section-title">Lista de auditoría</h2><div class="checklist">${auditCriteria.map((c,i)=>{const d=state.auditDetails[i]||{result:'Pendiente',evidence:'',comment:''};return `<div class="check-row"><b>${i+1}</b><div><strong>${c}</strong><input name="auditEvidence-${i}" placeholder="Evidencia" value="${esc(d.evidence)}"><input name="auditComment-${i}" placeholder="Comentario / hallazgo" value="${esc(d.comment)}"></div><select name="auditResult-${i}">${['Pendiente','Conforme','No conforme','Observación','No aplica'].map(x=>`<option ${d.result===x?'selected':''}>${x}</option>`).join('')}</select></div>`}).join('')}</div><div class="form-actions"><button class="primary-btn">Guardar auditoría</button></div></form></section>`);
}

function actions(){
  return page('No conformidades y acciones correctivas','No cierres una acción sin evidencia de implementación y comprobación de eficacia.',
  `<section class="card"><form id="actionForm">${preset('action-case')}<div class="form-grid">${field('Folio','folio','AC-'+String(state.actions.length+1).padStart(3,'0'))}${field('Origen','origin','Incidente')}${field('Descripción','description','', 'text',true)}${field('Evidencia de origen','evidence','', 'text',true)}${field('Riesgo relacionado','risk','R-01')}${field('Corrección inmediata','correction','', 'text',true)}${field('Causa raíz (cinco porqués)','cause','', 'text',true)}${field('Acción correctiva','action','', 'text',true)}${field('Responsable','responsible')}${field('Fecha compromiso','due','','date')}<div class="field"><label for="actionStatus">Estado</label><select id="actionStatus"><option>Abierta</option><option>En proceso</option><option>Pendiente de verificación</option><option>Cerrada</option><option>Reabierta</option></select></div>${field('Evidencia de implementación','implementationEvidence','', 'text',true)}${field('Verificación de eficacia','effectiveness','', 'text',true)}${field('Fecha de cierre','closedAt','','date')}</div><div class="form-actions"><button class="primary-btn">Guardar acción</button></div></form></section><section class="card" style="margin-top:18px"><div class="table-wrap"><table class="data-table"><thead><tr><th>Folio</th><th>Descripción</th><th>Responsable</th><th>Compromiso</th><th>Eficacia</th><th>Estado</th></tr></thead><tbody>${state.actions.length?state.actions.map((a,i)=>`<tr><td>${esc(a.folio)}</td><td>${esc(a.description)}</td><td>${esc(a.responsible)}</td><td>${esc(a.due)}</td><td>${esc(a.effectiveness||'Pendiente')}</td><td><select data-action-status="${i}">${['Abierta','En proceso','Pendiente de verificación','Cerrada','Reabierta'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No hay acciones correctivas.</td></tr>'}</tbody></table></div></section>`);
}

const previousBindForms=bindForms;
window.enhancedForms=true;
bindForms=function(){
  previousBindForms();
  $('#diagnosisForm')?.addEventListener('submit',e=>{e.preventDefault();const next=state.diagnosis.map((d,i)=>({...d,result:$(`[name=result-${i}]`).value,observation:$(`[name=observation-${i}]`).value.trim(),evidence:$(`[name=evidence-${i}]`).value.trim(),evaluator:$(`[name=evaluator-${i}]`).value.trim(),date:$(`[name=date-${i}]`).value,justification:$(`[name=justification-${i}]`)?.value.trim()||''}));if(next.some(d=>d.result==='No aplica'&&!d.justification)){toast('Cada No aplica necesita una justificación');return}state.diagnosis=next;save();toast('Diagnóstico detallado guardado');render('diagnosis')});
  $('#procedureForm')?.addEventListener('submit',e=>{e.preventDefault();if(!val('procedureName')||!val('procedurePurpose')||!val('procedureResponsible')){toast('Nombre, propósito y responsable son obligatorios');return}state.procedures.push({id:'SOP-'+String(state.procedures.length+1).padStart(2,'0'),name:val('procedureName'),purpose:val('procedurePurpose'),scope:val('procedureScope'),responsible:val('procedureResponsible'),steps:val('procedureSteps'),records:val('procedureRecords'),deviation:val('procedureDeviation')});save();toast('Procedimiento agregado');render('controls')});
  $('#inspectionForm')?.addEventListener('submit',e=>{e.preventDefault();const points=inspectionPoints.map((_,i)=>$(`[name=point-${i}]`).value),notes=inspectionPoints.map((_,i)=>$(`[name=pointNote-${i}]`).value.trim()), invalid=points.map((p,i)=>(p==='No conforme'||p==='No aplica')&&!notes[i]).some(Boolean), pending=points.includes('Pendiente'), non=points.includes('No conforme'),result=val('inspectionResult');if(invalid){toast('Cada punto No conforme o No aplica necesita observación');return}if((pending||non)&&result==='Liberada'){toast('No se puede liberar: hay puntos pendientes o no conformes');return}state.inspections.push({folio:val('folio'),dateTime:val('dateTime'),carrier:val('carrier'),driver:val('driver'),plate:val('plate'),trailer:val('trailer'),shipment:val('shipment'),inspector:val('inspector'),evidence:val('evidence'),result,points,pointNotes:notes,observations:val('inspectionObs')});save();toast('Inspección detallada guardada');render('inspections')});
  $('#auditForm')?.addEventListener('submit',e=>{e.preventDefault();state.auditDetails=auditCriteria.map((criterion,i)=>({criterion,result:$(`[name=auditResult-${i}]`).value,evidence:$(`[name=auditEvidence-${i}]`).value.trim(),comment:$(`[name=auditComment-${i}]`).value.trim()}));const result=state.auditDetails.filter(x=>x.result==='No conforme').length?'No conforme':state.auditDetails.filter(x=>x.result==='Observación').length?'Con observaciones':'Conforme';state.audit.push({date:val('auditDate'),auditor:val('auditor'),result});save();toast('Auditoría detallada guardada');render('audit')});
  $('#actionForm')?.addEventListener('submit',e=>{e.preventDefault();if(!val('description')||!val('responsible')||!val('due')){toast('Descripción, responsable y fecha compromiso son obligatorios');return}const status=val('actionStatus');if(status==='Cerrada'&&(!val('implementationEvidence')||!val('effectiveness')||!val('closedAt'))){toast('Una acción cerrada necesita implementación, eficacia y fecha de cierre');return}state.actions.push({folio:val('folio'),origin:val('origin'),description:val('description'),evidence:val('evidence'),risk:val('risk'),correction:val('correction'),cause:val('cause'),action:val('action'),responsible:val('responsible'),due:val('due'),status,implementationEvidence:val('implementationEvidence'),effectiveness:val('effectiveness'),closedAt:val('closedAt')});save();toast('Acción correctiva guardada');render('actions')});
}
render();
